171	    setLevel(j.value("power", ui->levelSpin->value()));
172	    setPort(j.value("port", 0));
173	    if(j.contains("sweep")) {
174	        auto sweep = j["sweep"];
175	        // extract sweep settings, keeping current values as default
176	        ui->span->setValue(sweep.value("span", ui->span->value()));
177	        ui->steps->setValue(sweep.value("steps", ui->steps->value()));
178	        ui->dwell->setValue(sweep.value("dwell", ui->dwell->value()));
