185	void SignalgeneratorWidget::deviceInfoUpdated()
186	{
187	    auto port = getDeviceStatus().port;
188	    for(auto cb : portCheckboxes) {
189	        delete cb;
190	    }
191	    portCheckboxes.clear();
192	    auto info = DeviceDriver::getInfo(window->getDevice());
193	    for(unsigned int i=1;i<=info.Limits.Generator.ports;i++) {
194	        auto cb = new QCheckBox("Port "+QString::number(i));
195	        ui->portBox->layout()->addWidget(cb);
196	        portCheckboxes.push_back(cb);
197	        connect(cb, &QCheckBox::toggled, [=](bool enabled){
198	            if(enabled) {
199	                for(auto other : portCheckboxes) {
200	                    if(other != cb) {
201	                        other->blockSignals(true);
202	                        other->setChecked(false);
203	                        other->blockSignals(false);
204	                    }
205	                }
206	            }
207	            emit SettingsChanged();
208	        });
209	    }
210	
211	    setFrequency(ui->frequency->value());
212	    setLevel(ui->levelSpin->value());
213	
214	    setPort(port);
215	
216	    ui->levelSlider->setMaximum(info.Limits.Generator.maxdBm * 100);
217	    ui->levelSlider->setMinimum(info.Limits.Generator.mindBm * 100);
218	    ui->levelSpin->setMaximum(info.Limits.Generator.maxdBm);
219	    ui->levelSpin->setMinimum(info.Limits.Generator.mindBm);
