222	void SignalgeneratorWidget::setLevel(double level)
223	{
224	    auto info = DeviceDriver::getInfo(window->getDevice());
225	    if(level < info.Limits.Generator.mindBm) {
226	        level = info.Limits.Generator.mindBm;
227	    }
228	    if(level > info.Limits.Generator.maxdBm) {
229	        level = info.Limits.Generator.maxdBm;
230	    }
231	    ui->levelSpin->blockSignals(true);
232	    ui->levelSlider->blockSignals(true);
233	    ui->levelSpin->setValue(level);
234	    ui->levelSlider->setValue(level * 100.0);
235	    ui->levelSpin->blockSignals(false);
236	    ui->levelSlider->blockSignals(false);
237	    SettingsChanged();
238	}
