240	void SignalgeneratorWidget::setFrequency(double frequency)
241	{
242	    auto info = DeviceDriver::getInfo(window->getDevice());
243	    if(frequency < info.Limits.Generator.minFreq) {
244	        frequency = info.Limits.Generator.minFreq;
245	    }
246	    if(frequency > info.Limits.Generator.maxFreq) {
247	        frequency = info.Limits.Generator.maxFreq;
248	    }
249	    ui->frequency->setValue(frequency);
250	}
251	
252	void SignalgeneratorWidget::setPort(unsigned int port)
253	{
254	    if(port > portCheckboxes.size()) {
255	        return;
256	    }
257	    if(port == 0) {
258	        for(auto cb : portCheckboxes) {
259	            cb->setChecked(false);
260	        }
261	    } else {
262	        portCheckboxes[port-1]->setChecked(true);
263	    }
264	}
